"use client";

import { useState } from "react";
import { MINDUP_PILLARS as PILLARS, type MindUpPillar } from "@/lib/mindup";

// The 6 Pillars of MIND UP — an interactive SVG donut. Desktop: hover a
// segment to highlight it and fill the info card; click to pin. Mobile: tap a
// segment to open its card below, tap again to close. Self-contained, no deps.

const CX = 200;
const CY = 200;
const OUTER = 188;
const INNER = 110;
const MID = (OUTER + INNER) / 2;
const GAP = 1.5; // degrees of white divider per segment edge

// Six equal 60° wedges, running clockwise from M. Each segment carries only
// its letter; the pillar details live in the info card.
const STEP = 360 / PILLARS.length;

const polar = (angleDeg: number, radius: number): [number, number] => {
  const rad = ((angleDeg - 90) * Math.PI) / 180;
  return [CX + radius * Math.cos(rad), CY + radius * Math.sin(rad)];
};

function sectorPath(startDeg: number, endDeg: number): string {
  const s = startDeg + GAP;
  const e = endDeg - GAP;
  const [ox, oy] = polar(s, OUTER);
  const [ex, ey] = polar(e, OUTER);
  const [ix, iy] = polar(e, INNER);
  const [jx, jy] = polar(s, INNER);
  const large = e - s > 180 ? 1 : 0;
  return [
    `M ${ox} ${oy}`,
    `A ${OUTER} ${OUTER} 0 ${large} 1 ${ex} ${ey}`,
    `L ${ix} ${iy}`,
    `A ${INNER} ${INNER} 0 ${large} 0 ${jx} ${jy}`,
    "Z",
  ].join(" ");
}

function SegmentLabel({ id, centerDeg }: { id: string; centerDeg: number }) {
  const [x, y] = polar(centerDeg, MID);
  return (
    <text
      x={x}
      y={y}
      className="font-display"
      textAnchor="middle"
      dominantBaseline="central"
      fontSize={46}
      fontWeight={800}
      fill="#ffffff"
    >
      {id}
    </text>
  );
}

function PillarBody({ pillar }: { pillar: MindUpPillar }) {
  return (
    <ul className="mt-4 grid grid-cols-1 gap-1.5 sm:grid-cols-2">
      {pillar.items.map((item) => (
        <li key={item} className="flex items-center gap-2 text-sm text-muted-foreground">
          <span
            aria-hidden="true"
            className="h-1.5 w-1.5 shrink-0 rounded-full"
            style={{ backgroundColor: pillar.color }}
          />
          {item}
        </li>
      ))}
    </ul>
  );
}

export function MindUpPillars() {
  const [pinned, setPinned] = useState<string | null>(null);
  const [hover, setHover] = useState<string | null>(null);

  const display = pinned ?? hover;
  const activePillar = display
    ? (PILLARS.find((p) => p.id === display) ?? null)
    : null;

  const hoverDevice = () =>
    typeof window !== "undefined" && window.matchMedia("(hover: hover)").matches;

  const onEnter = (id: string) => {
    if (hoverDevice()) setHover(id);
  };
  const onLeave = () => {
    if (hoverDevice()) setHover(null);
  };
  const onActivate = (id: string) => {
    setPinned((prev) => (prev === id ? null : id));
    if (hoverDevice()) setHover(id);
  };

  return (
    <section
      aria-label="The six pillars of MIND UP"
      data-animate-group
      className="mx-auto mt-12 md:mt-16 max-w-4xl"
    >
      <div className="grid items-center gap-12 md:grid-cols-[minmax(0,30rem)_1fr] md:gap-14 lg:gap-20">
        {/* ---------- Donut ---------- */}
        <div
          data-animate-item
          className="mx-auto w-full max-w-[19rem] sm:max-w-[22rem] md:max-w-[26rem]"
        >
          <div
            className="relative aspect-square w-full select-none"
            role="group"
            aria-label="MIND UP — six pillars. Use the letters to explore each pillar."
          >
            <svg
              viewBox="0 0 400 400"
              className="h-full w-full drop-shadow-[0_22px_34px_rgba(0,0,0,0.16)]"
              role="img"
              aria-labelledby="mindup-pillars-title"
            >
              <title id="mindup-pillars-title">
                MIND UP Theory — The Unshakable Life
              </title>
              {/* White ring behind the segments forms the thin dividers */}
              <circle
                cx={CX}
                cy={CY}
                r={MID}
                fill="none"
                stroke="#ffffff"
                strokeWidth={OUTER - INNER + 2}
              />
              {PILLARS.map((p, i) => {
                const start = -90 - STEP / 2 + i * STEP;
                const active = display === p.id;
                const centerDeg = start + STEP / 2;
                return (
                  <g
                    key={p.id}
                    role="button"
                    tabIndex={0}
                    aria-label={`${p.id} — ${p.title}: ${p.items.join(", ")}`}
                    aria-pressed={active}
                    onMouseEnter={() => onEnter(p.id)}
                    onMouseLeave={onLeave}
                    onFocus={() => onEnter(p.id)}
                    onBlur={onLeave}
                    onClick={() => onActivate(p.id)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" || e.key === " ") {
                        e.preventDefault();
                        onActivate(p.id);
                      }
                    }}
                    className="cursor-pointer focus:outline-none focus-visible:opacity-90"
                    style={{
                      transform: active ? "scale(1.05)" : "scale(1)",
                      transformBox: "fill-box",
                      transformOrigin: "center",
                      transition: "transform 0.25s ease",
                    }}
                  >
                    <path
                      d={sectorPath(start, start + STEP)}
                      fill={p.color}
                      stroke={p.color}
                      strokeWidth={2}
                      strokeLinejoin="round"
                      strokeLinecap="round"
                      style={{
                        filter: active
                          ? "drop-shadow(0 10px 16px rgba(0,0,0,0.18)) brightness(1.05)"
                          : undefined,
                        transition: "filter 0.25s ease",
                      }}
                    />
                    <SegmentLabel id={p.id} centerDeg={centerDeg} />
                  </g>
                );
              })}
            </svg>

            {/* Centre disc — MIND UP / THEORY / The Unshakable Life */}
            <div
              aria-hidden="true"
              className="pointer-events-none absolute left-1/2 top-1/2 flex h-[50%] w-[50%] -translate-x-1/2 -translate-y-1/2 flex-col items-center justify-center rounded-full bg-card text-center shadow-[0_14px_30px_-12px_rgba(0,0,0,0.2)] ring-1 ring-border"
            >
              <p className="font-display text-[1.35rem] sm:text-[1.5rem] md:text-[1.7rem] font-extrabold uppercase leading-none tracking-[0.12em] text-foreground">
                Mind Up
              </p>
              <p className="mt-2 text-[0.65rem] font-bold uppercase leading-none tracking-[0.42em] text-accent-strong">
                Theory
              </p>
              <span aria-hidden="true" className="mt-2.5 h-px w-10 bg-border" />
              <p className="mt-2.5 px-5 font-display text-[0.75rem] sm:text-[0.8rem] leading-snug text-muted-foreground">
                The Unshakable Life
              </p>
            </div>
          </div>
        </div>

        {/* ---------- Info card ---------- */}
        <div data-animate-item className="w-full">
          {/* Desktop: side card */}
          <div className="hidden md:block">
            {activePillar ? (
              <div
                key={activePillar.id}
                className="pillar-card-enter rounded-3xl border border-border bg-card p-6 shadow-[0_20px_44px_-22px_rgba(0,0,0,0.25)]"
              >
                <div className="flex items-center gap-3">
                  <span
                    aria-hidden="true"
                    className="grid h-11 w-11 shrink-0 place-items-center rounded-xl font-display text-lg font-extrabold text-white"
                    style={{ backgroundColor: activePillar.color }}
                  >
                    {activePillar.id}
                  </span>
                  <div>
                    <h3 className="font-display text-lg font-bold leading-tight">
                      {activePillar.title}
                    </h3>
                    <p className="text-xs text-muted-foreground">
                      {activePillar.tagline}
                    </p>
                  </div>
                </div>
                <PillarBody pillar={activePillar} />
              </div>
            ) : (
              <div
                key="default"
                className="pillar-card-enter rounded-3xl border border-border bg-card p-6 shadow-[0_20px_44px_-22px_rgba(0,0,0,0.25)]"
              >
                <p className="font-display text-sm font-extrabold uppercase tracking-[0.18em]">
                  Mind Up
                </p>
                <p className="mt-0.5 text-[0.62rem] font-bold uppercase tracking-[0.4em] text-accent-strong">
                  Theory
                </p>
                <p className="mt-3 text-sm leading-relaxed text-muted-foreground">
                  Six pillars that keep life unshakable — master your mind,
                  invest in health, nurture relationships, develop skills and
                  work, unlock yourself, and progress daily while resetting
                  often.
                </p>
                <div className="mt-4 flex flex-wrap items-center gap-1.5">
                  {["M", "I", "N", "D", "U", "P"].map((letter) => {
                    const p = PILLARS.find((x) => x.id === letter)!;
                    return (
                      <span
                        key={p.id}
                        aria-hidden="true"
                        className="grid h-7 w-7 place-items-center rounded-full font-display text-xs font-extrabold text-white"
                        style={{ backgroundColor: p.color }}
                      >
                        {p.id}
                      </span>
                    );
                  })}
                </div>
                <p className="mt-4 text-xs text-muted-foreground">
                  Hover or tap a pillar to explore it.
                </p>
              </div>
            )}
          </div>

          {/* Mobile: card below the donut */}
          <div className="md:hidden">
            {activePillar ? (
              <div
                key={activePillar.id}
                className="pillar-card-enter rounded-3xl border border-border bg-card p-5 shadow-[0_20px_44px_-22px_rgba(0,0,0,0.25)]"
              >
                <div className="flex items-center gap-3">
                  <span
                    aria-hidden="true"
                    className="grid h-10 w-10 shrink-0 place-items-center rounded-xl font-display text-base font-extrabold text-white"
                    style={{ backgroundColor: activePillar.color }}
                  >
                    {activePillar.id}
                  </span>
                  <div>
                    <h3 className="font-display text-base font-bold leading-tight">
                      {activePillar.title}
                    </h3>
                    <p className="text-xs text-muted-foreground">
                      {activePillar.tagline}
                    </p>
                  </div>
                </div>
                <PillarBody pillar={activePillar} />
                <p className="mt-3 text-center text-[11px] text-muted-foreground">
                  Tap the pillar again to close
                </p>
              </div>
            ) : (
              <p className="text-center text-sm text-muted-foreground">
                Tap a pillar to see what it includes.
              </p>
            )}
          </div>
        </div>
      </div>
    </section>
  );
}